WORKDESK_HTML = r"""
<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Digital Legal Concierge — рабочий стол</title>
<style>
:root{--bg:#f4f6fa;--card:#fff;--ink:#172033;--muted:#667085;--line:#e4e7ec;--blue:#3157d5;--blue2:#eef2ff;--red:#b42318;--red2:#fef3f2;--amber:#a15c00;--amber2:#fff7e6;--green:#14804a}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Arial,sans-serif}header{padding:17px 22px;background:linear-gradient(135deg,#111827,#26334f);color:#fff;display:flex;justify-content:space-between;gap:14px;align-items:center}h1{font-size:20px;margin:0 0 3px}header p{margin:0;color:#d0d5dd;font-size:13px}.links{display:flex;gap:8px;flex-wrap:wrap}.links a,.links button{color:#fff;background:transparent;border:1px solid #ffffff42;border-radius:9px;padding:8px 10px;text-decoration:none}.layout{display:grid;grid-template-columns:210px minmax(0,1fr) 370px;min-height:calc(100vh - 72px)}nav,.side{background:var(--card);padding:16px}nav{border-right:1px solid var(--line)}.side{border-left:1px solid var(--line)}main{padding:20px;overflow:auto}.nav{width:100%;border:0;background:transparent;text-align:left;padding:10px;border-radius:10px;font-weight:700;cursor:pointer}.nav:hover,.nav.active{background:var(--blue2);color:#2445b5}.toolbar,.row,.head{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.toolbar,.head{justify-content:space-between}.card,.item{background:var(--card);border:1px solid var(--line);border-radius:14px}.card{padding:15px}.metrics,.queues{display:grid;gap:10px}.metrics{grid-template-columns:repeat(4,1fr)}.queues{grid-template-columns:repeat(2,1fr);margin-top:14px}.metric,.queue{border:1px solid var(--line);background:#fff;border-radius:12px;padding:13px;text-align:left;cursor:pointer}.metric b,.queue b{display:block}.metric b{font-size:25px}.metric span,.muted{font-size:13px;color:var(--muted)}.metric.warn{background:var(--amber2)}.metric.bad{background:var(--red2)}.queue .count{float:right;font-size:21px}.item{padding:13px;margin:9px 0}.badge{display:inline-flex;border-radius:999px;background:#eef2f6;padding:4px 8px;margin:2px;font-size:12px;font-weight:700}.badge.red{background:var(--red2);color:var(--red)}.badge.amber{background:var(--amber2);color:var(--amber)}button,.button{border:0;border-radius:9px;padding:9px 11px;background:var(--blue);color:#fff;font-weight:700;cursor:pointer;text-decoration:none;display:inline-block}button.secondary,.button.secondary{background:#475467}button.green{background:var(--green)}button:disabled{opacity:.55}.empty,.loading,.error{padding:25px;text-align:center;border:1px dashed var(--line);border-radius:12px;color:var(--muted)}.error{background:var(--red2);color:var(--red)}.action{background:var(--blue2);border:1px solid #c7d2fe;border-radius:11px;padding:12px;margin:12px 0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}.cell{background:#f8fafc;border-radius:9px;padding:10px}.cell span{display:block;color:var(--muted);font-size:12px}.section{border-top:1px solid var(--line);padding-top:13px;margin-top:13px}.feedback{min-height:21px;font-size:13px}.feedback.ok{color:var(--green)}.feedback.bad{color:var(--red)}@media(max-width:1100px){.layout{grid-template-columns:190px 1fr}.side{grid-column:1/-1;border-left:0;border-top:1px solid var(--line)}}@media(max-width:720px){header{align-items:flex-start;flex-direction:column}.layout{display:block}nav{display:flex;overflow:auto;gap:5px}.nav{width:auto;white-space:nowrap}main,.side{padding:13px}.metrics,.queues{grid-template-columns:1fr 1fr}}@media(max-width:460px){.metrics,.queues,.grid{grid-template-columns:1fr}}
</style></head><body>
<header><div><h1>⚖ Единый рабочий стол</h1><p>Приоритет → дело → одно безопасное действие.</p></div><div class="links"><a href="/message-center/ui">Сообщения</a><a href="/admin-ui">Расширенная панель</a><a href="/operator">Все разделы</a><form method="post" action="/logout"><button>Выйти</button></form></div></header>
<div class="layout"><nav><button class="nav active" data-v="overview" onclick="overview(this)">Приоритеты</button><button class="nav" data-v="unassigned" onclick="openQueue('unassigned',this)">Без юриста</button><button class="nav" data-v="documents" onclick="openQueue('documents',this)">Документы</button><button class="nav" data-v="consultations" onclick="openQueue('consultations',this)">Консультации</button><button class="nav" data-v="overdue" onclick="openQueue('overdue',this)">Просрочки</button></nav>
<main><div class="toolbar"><div><b id="title">Приоритеты</b><div id="fresh" class="muted"></div></div><button class="secondary" onclick="reload(this)">Обновить</button></div><div id="feedback" class="feedback" role="status"></div><div id="view" class="card"><div class="loading">Загрузка…</div></div></main><aside class="side"><h3>Карточка дела</h3><div id="caseView" class="muted">Откройте дело из списка.</div></aside></div>
<script>
let token='',mode='overview',queue='unassigned',selected=null,busy=false,attention=new Map();const v=document.getElementById('view'),cv=document.getElementById('caseView'),fb=document.getElementById('feedback'),fresh=document.getElementById('fresh'),title=document.getElementById('title');const titles={unassigned:'Дела без юриста',documents:'Документы на проверке',consultations:'Консультации сегодня',overdue:'Просроченные действия'};
function e(x){return String(x??'').replace(/[&<>\x22\x27]/g,c=>c==='&'?'&amp;':c==='<'?'&lt;':c==='>'?'&gt;':c.charCodeAt(0)===34?'&quot;':'&#39;')}function dt(x){if(!x)return'—';try{return new Intl.DateTimeFormat('ru-RU',{dateStyle:'short',timeStyle:'short'}).format(new Date(x))}catch{return x}}function say(x,c=''){fb.textContent=x;fb.className='feedback '+c}function active(b){document.querySelectorAll('.nav').forEach(x=>x.classList.toggle('active',x===b))}function load(){v.innerHTML='<div class="loading">Загрузка…</div>'}function err(x,retry){v.innerHTML=`<div class="error"><b>Не удалось загрузить данные</b><p>${e(x.message||x)}</p><button onclick="${retry}">Повторить</button></div>`}
async function api(path,opt={}){if(!token)throw Error('Персональная сессия не загружена');const r=await fetch(path,{...opt,credentials:'same-origin',cache:'no-store',headers:{'x-admin-token':token,'Content-Type':'application/json',...(opt.headers||{})}});if(r.status===401||r.status===403){location.href='/login';throw Error('Сессия истекла')}const d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.detail||'Ошибка запроса');return d}
function badges(r){return(r||[]).map(x=>`<span class="badge ${x.code==='overdue'?'red':x.code==='unassigned'?'amber':''}">${e(x.label)}</span>`).join('')}function primary(x){const a=x.primary_action||{};return a.kind==='auto_assign'?`<button class="green" onclick="assign(${x.id},this)">${e(a.label)}</button>`:`<a class="button" href="${e(a.href||'/admin/workdesk/ui')}">${e(a.label||'Открыть')}</a>`}function item(x){return`<article class="item"><div class="head"><div><b>${e(x.number)}</b><div class="muted">${e(x.route_label)} · обновлено ${dt(x.updated_at)}</div></div><span class="badge ${String(x.sla_status).includes('OVERDUE')?'red':''}">${e(x.status_label)}</span></div><div>${badges(x.reasons)}</div><p>${e(x.next_action)}</p><div class="muted">Ответственный: ${e(x.lawyer_name||'не назначен')} · ${e(x.sla_label)}</div><div class="row" style="margin-top:9px">${primary(x)}<button class="secondary" onclick="openCase(${x.id})">Карточка</button><a class="button secondary" href="/message-center/ui?case_id=${x.id}">Переписка</a></div></article>`}function qaction(x){if(queue==='unassigned')return`<button class="green" onclick="assign(${x.id},this)">Назначить юриста</button>`;if(queue==='documents')return'<a class="button" href="/document-access/review/ui">Проверить документы</a>';if(queue==='consultations')return'<a class="button" href="/admin/consultation-outcomes/ui">Открыть консультации</a>';return'<a class="button" href="/admin/sla/ui">Открыть SLA</a>'}
async function boot(){try{const r=await fetch('/auth/session',{credentials:'same-origin',cache:'no-store'});if(!r.ok){location.href='/login';return}const s=await r.json();if(!(s.roles||[s.role]).includes('admin'))throw Error('Требуется роль администратора');token=s.api_token||'';await loadOverview()}catch(x){err(x,'boot()')}}async function overview(b){mode='overview';active(b);title.textContent='Приоритеты';await loadOverview()}
async function loadOverview(){load();say('');try{const[d,a]=await Promise.all([api('/admin/dashboard'),api('/admin/workdesk/attention')]);fresh.textContent='Обновлено '+dt(a.generated_at);attention=new Map((a.items||[]).map(x=>[x.id,x]));const rows=(a.items||[]).map(item).join('');v.innerHTML=`<div class="metrics"><button class="metric" onclick="openQueue('unassigned',document.querySelector('[data-v=unassigned]'))"><b>${d.cases?.active||0}</b><span>активных дел</span></button><button class="metric warn" onclick="openQueue('unassigned',document.querySelector('[data-v=unassigned]'))"><b>${d.queue?.unassigned||0}</b><span>без юриста</span></button><button class="metric ${d.queue?.overdue?'bad':''}" onclick="openQueue('overdue',document.querySelector('[data-v=overdue]'))"><b>${d.queue?.overdue||0}</b><span>SLA-просрочек</span></button><button class="metric" onclick="openQueue('consultations',document.querySelector('[data-v=consultations]'))"><b>${d.consultations?.today||0}</b><span>консультаций сегодня</span></button></div><h2>Сделать сейчас <span class="badge">${a.total||0}</span></h2>${rows||'<div class="empty"><b>Срочных действий нет</b><p>Очереди пусты или уже обработаны.</p></div>'}<div class="queues">${qc('unassigned','Назначить юриста',d.queue?.unassigned)}${qc('documents','Проверить документы',d.queue?.documents_review)}${qc('consultations','Провести консультации',d.queue?.consultations_today)}${qc('overdue','Устранить просрочки',d.queue?.overdue)}</div>`}catch(x){err(x,'loadOverview()')}}function qc(k,t,n){return`<button class="queue" onclick="openQueue('${k}',document.querySelector('[data-v=${k}]'))"><span class="count">${n||0}</span><b>${e(t)}</b><div class="muted">Открыть рабочую очередь</div></button>`}
async function openQueue(n,b){mode='queue';queue=n;active(b);title.textContent=titles[n];load();say('');try{const d=await api('/admin/work-queues/'+encodeURIComponent(n));fresh.textContent='Обновлено '+dt(d.generated_at);const rows=(d.items||[]).map(x=>`<article class="item"><div class="head"><div><b>${e(x.number)}</b><div class="muted">${e(x.route_label)} · создано ${dt(x.created_at)}</div></div><span class="badge ${String(x.sla_status).includes('OVERDUE')?'red':''}">${e(x.status_label)}</span></div><p>${e(x.next_action)}</p><div class="muted">Ответственный: ${e(x.lawyer_name||'не назначен')} · ${e(x.sla_label)}</div><div class="row" style="margin-top:9px">${qaction(x)}<button class="secondary" onclick="openCase(${x.id})">Карточка</button><a class="button secondary" href="/message-center/ui?case_id=${x.id}">Переписка</a></div></article>`).join('');v.innerHTML=rows||'<div class="empty"><b>Очередь пуста</b><p>На текущий момент действий нет.</p></div>'}catch(x){err(x,`openQueue('${n}',document.querySelector('[data-v=${n}]'))`)} }
async function openCase(id){selected=id;cv.innerHTML='<div class="loading">Загрузка…</div>';say('');try{const d=await api('/admin/case-workspace/'+id),docs=(d.documents||[]).map(x=>`<div class="item"><b>${e(x.title)}</b><div class="muted">${e(x.status_label)} · версия ${e(x.version||1)}</div>${x.lawyer_comment?`<div class="feedback">Комментарий: ${e(x.lawyer_comment)}</div>`:''}</div>`).join('')||'<div class="muted">Документов пока нет.</div>';const assignButton=!d.case.lawyer_id?`<button class="green" onclick="assign(${id},this)">Назначить юриста</button>`:'';cv.innerHTML=`<h3>${e(d.case.number)}</h3><span class="badge ${String(d.case.sla_status).includes('OVERDUE')?'red':''}">${e(d.case.status_label)}</span><div class="action"><b>Рекомендуемое действие</b><br>${e(d.case.next_action)}</div><div class="grid"><div class="cell"><span>Услуга</span>${e(d.case.route_label)}</div><div class="cell"><span>Ответственный</span>${e(d.case.lawyer_name||'не назначен')}</div><div class="cell"><span>SLA</span>${e(d.case.sla_label)}</div><div class="cell"><span>Срок</span>${dt(d.case.sla_due_at)}</div></div><div class="section row">${assignButton}<a class="button" href="/message-center/ui?case_id=${id}">Переписка</a><a class="button secondary" href="/document-access/review/ui">Документы</a><a class="button secondary" href="/admin/consultation-outcomes/ui">Консультации</a><a class="button secondary" href="/admin/sla/ui">SLA</a></div>${d.client?`<div class="section"><b>Клиент</b><div>${e(d.client.name||'Имя не указано')}</div><div class="muted">${d.client.username?'@'+e(d.client.username):'Telegram username не указан'}</div></div>`:''}<div class="section"><b>Документы</b>${docs}</div><div class="section"><div class="muted">Редкое исправление статуса выполняется только в расширенной панели с комментарием и аудитом.</div><a class="button secondary" href="/admin-ui">Расширенная панель</a></div>`}catch(x){cv.innerHTML=`<div class="error">${e(x.message||x)}<br><button onclick="openCase(${id})">Повторить</button></div>`}}
async function assign(id,b){if(busy)return;busy=true;b.disabled=true;const old=b.textContent;b.textContent='Назначение…';try{const cached=attention.get(id),d=await api('/admin/case-workspace/'+id);await api('/admin/cases/'+id+'/auto-assign',{method:'POST',body:JSON.stringify({expected_lawyer_id:null,expected_status:cached?.status||d.case.status})});say('Юрист назначен. Карточка и очередь обновлены.','ok');await openCase(id);if(mode==='queue')await openQueue(queue,document.querySelector('[data-v='+queue+']'));else await loadOverview()}catch(x){say('Назначение не выполнено: '+(x.message||x),'bad');await openCase(id)}finally{busy=false;b.disabled=false;b.textContent=old}}
async function reload(b){if(busy)return;b.disabled=true;const old=b.textContent;b.textContent='Обновление…';try{if(mode==='queue')await openQueue(queue,document.querySelector('[data-v='+queue+']'));else await loadOverview();if(selected)await openCase(selected)}finally{b.disabled=false;b.textContent=old}}boot();
</script></body></html>
"""